<?php
require_once "_bootstrap.php";
$resultStmt = $pdo->prepare("SELECT r.*, c.code, c.title FROM student_results r INNER JOIN courses c ON c.id = r.course_id WHERE r.student_id = :student_id AND r.status = 'Published' ORDER BY r.academic_year DESC, c.code");
$resultStmt->execute(["student_id" => $student["id"]]);
$results = $resultStmt->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Results | RAO HBMIS</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="portal-body"><header class="portal-topbar"><a class="portal-brand" href="index.php"><span>RAO</span> Student Portal</a><a href="../auth/logout.php">Log out</a></header><main class="portal-main"><p><a href="index.php">&larr; Student portal</a></p><section class="portal-intro"><div><p class="eyebrow">ACADEMICS</p><h1>View results</h1><p>Your published examination results.</p></div></section><section class="portal-panel"><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Code</th><th>Course</th><th>Year</th><th>Grade</th><th>Score</th></tr></thead><tbody><?php if (!$results): ?><tr><td colspan="5" class="empty-state">No published results available.</td></tr><?php else: foreach ($results as $result): ?><tr><td><?php echo $e($result["code"]); ?></td><td><?php echo $e($result["title"]); ?></td><td><?php echo $e($result["academic_year"]); ?></td><td><strong><?php echo $e($result["grade"]); ?></strong></td><td><?php echo $e($result["score"]); ?>%</td></tr><?php endforeach; endif; ?></tbody></table></div></section></main></body></html>
